def find_sequence(n, k):
    if n < k or n % k != 0:
        return -1

    base = n // k
    remainder = n % k
    result = [base] * k

    for i in range(k - 1, 0, -1):
        if remainder > 0:
            result[i] += 1
            remainder -= 1

    gcd = math.gcd(*result)

    if gcd == 1:
        return result

    for i in range(1, k):
        if result[i] - result[i - 1] > 1:
            result[i] -= 1
            result[i - 1] += 1
            gcd = math.gcd(*result)
            if gcd > 1:
                break

    if gcd == 1:
        return -1

    return result

